// TH18 v1.00a Stage 6 MainSub02 (st06.ecl.txt:1249-1261)
// and its GirlA03 / GirlA03_at closure (st06.ecl.txt:518-588).
// Ranks 0..3; source angles in radians, target in BAM/degrees.
const TIME_LIMIT: int = 1400;
const TH18_BALL2: int = 432; // source etSprite type5 color8; radius 4.
const BULLET_COLOR: int = 8;

// Source EX: ANIM a=1 (animation omitted; 4*initial-speed retreat kept via
// sh_dist(-2)), WAIT 60, VELTIME a=100 r=3.2 keeping the birth direction.
xformdef ACCEL {
    @60 add_speed(0fx);
    step_speed(3.2fx, 100);
}

// GirlA03_at: wait(10), then ten 10-shot bursts. Each shot re-reads
// etOffsetRad(%RANDRAD, %RANDF2*32) and etAngle(%RANDF2*0.034906585, 60deg).
async sub shots() {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var n: int = 1;          // etCount 1/1/3/3
    var gap: int = 200;      // burst gap E200 / N,H,L120
    if rank >= 1 { gap = 120; }
    if rank >= 2 { n = 3; }
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, BULLET_COLOR);
    sh_ring(0, 0);           // etAim mode0: aimed fan
    sh_aim(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, 0.5fx, 0fx); // etSpeed 0.5/1.0, M=1 -> first value
    sh_dist(0, -2fx);        // source ANIM retreat = 4*0.5px backwards
    sh_xform(0, ACCEL);
    for outer in 0..10 {
        for i in 0..10 {
            // Three independent config-time RANDF2/RANDRAD samples.
            var off_a: angle = rand(65536) as angle;
            var u_r: fx = (rand(65536)-32768) as fx / 32768;
            var u_a: fx = (rand(65536)-32768) as fx / 32768;
            sh_offset_rad(0, off_a, u_r*32fx);
            sh_angle(0, ((u_a*364fx) as int) as angle, 60deg);
            sh_fire(0);
            wait(2);
        }
        wait(gap);
    }
}

// GirlA03 entry: source boxes 24/16 and first velocity -90deg 0.8.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);       // 24x24 source radius
    set_hitbox(8fx);         // 16x16 source radius
    move_vel(0, -90deg, 0.8fx, EASE_LINEAR);
    spawn shots();
    wait(180);
    // moveVelTime(120, mode1, -0.7853982, 1.2); X mirror for the M-created twin.
    var turn: angle = -45deg;
    if mirror == 1 { turn = -135deg; }
    move_vel(120, turn, 1.2fx, EASE_QUAD_IN);
    loop { wait(1000); }
}

// MainSub02: four mirror pairs at 60-frame intervals.
async sub pattern() {
    wait(120);
    for i in 0..4 {
        _ = spawn_enemy(-160fx, 480fx, 1000, 0, 0, 0, girl(0));
        _ = spawn_enemy(160fx, 480fx, 1000, 0, 0, 0, girl(1));
        wait(60);
    }
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 10000, 0, 0, 0, control);
    loop { wait(600); }
}
